from contextlib import contextmanager

@contextmanager
def db_transaction(conn):
    try:
        yield conn          # caller receives conn via `as`
        conn.commit()
    except Exception:
        conn.rollback()
        raise               # re-raise so caller sees the error
    finally:
        conn.close()        # runs even if commit or rollback raises

