const dest = fs.createWriteStream('output.bin');

function pour(source) {
  source.on('data', (chunk) => {
    const ok = dest.write(chunk);
    if (!ok) {
      source.pause();                    // stop reading
      dest.once('drain', () => {
        source.resume();                 // buffer cleared — go again
      });
    }
  });
}

